"""
Task: task-cc306c1c
Rule: Replace all cells with value 3 by using symmetry.
For each cell equal to 3, find its three symmetric counterparts:
- 180° rotation: (15-r, 15-c)
- Horizontal mirror: (15-r, c)  
- Vertical mirror: (r, 15-c)
If all non-3 counterparts have the same value, replace the 3 with that value.
"""

def transform(grid):
    new_grid = [row[:] for row in grid]
    for r in range(16):
        for c in range(16):
            if grid[r][c] == 3:
                sym_positions = [(15-r, 15-c), (15-r, c), (r, 15-c)]
                non_3_values = set()
                for sr, sc in sym_positions:
                    val = grid[sr][sc]
                    if val != 3:
                        non_3_values.add(val)
                if len(non_3_values) == 1:
                    new_grid[r][c] = list(non_3_values)[0]
    return new_grid

